    // Null-terminate the buffer
    buf[14 + count] = '\0';

    // Copy all content in buf to out, ensuring null termination
    // Use snprintf to prevent buffer overflow
    snprintf(out, BUF_SIZE, "%s", buf);

    close(fd);
}
